curl -s -H "Authorization: Bearer <TOKEN>" "https://www.googleapis.com/calendar/v3/users/me/calendarList" | python3 -c "
import json, sys
data = json.load(sys.stdin)
for cal in data.get('items', []):
    location = cal.get('location', '')
    if location:
        print(f\"ID: {cal['id']}, Summary: {cal['summary']}, Location: {location}\")
    else:
        print(f\"ID: {cal['id']}, Summary: {cal['summary']}, Location: (none)\")
"
